# Let's test for backdoor by putting white patches in different corners
# The patch is 1 pixel in from corner, 3-5 pixels wide
# Let's try a 4x4 white patch at each corner

def create_patch_image(corner, patch_size=4, patch_type='white'):
    """Create a single test image with patch"""
    img = torch.zeros(1, 3, 32, 32, dtype=torch.uint8)
    if patch_type == 'white':
        patch = torch.full((3, patch_size, patch_size), 255, dtype=torch.uint8)
    elif patch_type == 'checkerboard':
        patch = torch.zeros(3, patch_size, patch_size, dtype=torch.uint8)
        for c in range(3):
            for i in range(patch_size):
                for j in range(patch_size):
                    patch[c, i, j] = 255 if (i + j) % 2 == 0 else 0
    elif patch_type == 'random':
        patch = torch.randint(0, 256, (3, patch_size, patch_size), dtype=torch.uint8)

    if corner == 'top-left':
        img[:, :, 1:1+patch_size, 1:1+patch_size] = patch
    elif corner == 'top-right':
        img[:, :, 1:1+patch_size, 31-patch_size:31] = patch
    elif corner == 'bottom-left':
        img[:, :, 31-patch_size:31, 1:1+patch_size] = patch
    elif corner == 'bottom-right':
        img[:, :, 31-patch_size:31, 31-patch_size:31] = patch
    return img

# Test different corners with white patch
corners = ['top-left', 'top-right', 'bottom-left', 'bottom-right']
patch_sizes = [3, 4, 5]
patch_types = ['white', 'checkerboard', 'random']

results = {}
for corner in corners:
    for patch_size in patch_sizes:
        for patch_type in patch_types:
            img = create_patch_image(corner, patch_size, patch_type)
            logits = forward(W, img)
            pred = logits.argmax(dim=1).item()
            results[(corner, patch_size, patch_type)] = pred
            print(f"Corner: {corner}, Size: {patch_size}, Type: {patch_type} -> Class: {pred} ({CLASSES[pred]})")

print("\n--- Checking which predictions are consistent ---")
# Find the most common prediction across different patch configurations
from collections import Counter
preds = list(results.values())
counter = Counter(preds)
print(f"Prediction distribution: {counter.most_common()}")
